{
  "title": "黑客入侵",
  "scene": "夜晚的赛博朋克都市霓虹闪烁，街道上行人稀少。你站在一家巨型企业的大楼前，周围是闪烁的电子屏幕和迷雾笼罩的停车场。大楼上有一个巨大的黑客入侵警告标志。你观察了许久，终于决定行动。",
  "goal": "找到并关闭大楼的监控系统，避免被发现。",
  "clue": "黑客入侵警告标志。",
  "choices": [
    {"id": "A", "text": "直接攻击大楼的主服务器", "outcome": "你迅速找到了主服务器的位置，但服务器的防护超出了你的能力范围，未能成功侵入。", "result": "fail", "next": "retry"},
    {"id": "B", "text": "尝试破解大楼停车场的监控摄像头", "outcome": "停车场的监控摄像头被你轻松破解，但最终发现这些摄像头并不是连接到大楼的安全系统的核心部分。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "利用街道上的电子屏幕传播虚假信息，分散大楼工作人员的注意力", "outcome": "你成功在电子屏幕上植入了虚假信息，成功吸引了工作人员的注意力，创造了入侵的窗口期。", "result": "success", "next": "next_level"}
  ]
}
